INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('our-impact','main','hero','{"lead": "Our Impact", "heading": "Stability that changes lives", "intro": "<p>Every placement is a child given room to grow \u2014 and a family supported at every step.</p>", "bg": "image-set(url(''/assets/uploads/2024/10/shutterstock_1575539629-2-2-1917.avif'') type(''image/avif''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2-2-1917.webp'') type(''image/webp''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2-2.jpg''))"}',0,'published','');
