INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('our-impact','main','imageText','{"reverse": false, "heading": "Trauma-informed care", "body": "<p>Our foster families are trained and supported to meet children exactly where they are.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-2-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-2-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-2.jpg", "w": "834", "h": "468"}}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('our-impact','main','imageText','{"reverse": true, "heading": "Round-the-clock support", "body": "<p>On-call guidance and a dedicated case team mean no family ever feels alone.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-3-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-3-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-3.jpg", "w": "834", "h": "468"}}',3,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('our-impact','main','cta','{"heading": "Ready to get started?", "body": "<p><strong>You can be the difference.</strong> Give a child the stability of a safe, supportive home.</p>", "label": "Become a foster parent", "href": "/become-a-foster-parent", "variant": "dark"}',4,'published','');
